<?php require_once __DIR__.'/_base.php'; $title='My Bookings'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['booking_id'];$reason=post('cancellation_reason');$s=$pdo->prepare("SELECT * FROM bookings WHERE id=? AND user_id=? AND status IN ('Pending','Accepted','Confirmed')");$s->execute([$id,$u['id']]);if($b=$s->fetch()){$pdo->prepare("UPDATE bookings SET status='Cancelled',cancellation_reason=?,updated_at=NOW() WHERE id=?")->execute([$reason,$id]);$pp=$pdo->prepare('SELECT user_id FROM providers WHERE id=?');$pp->execute([$b['provider_id']]);$pidUser=$pp->fetchColumn();notify($pdo,'Booking cancelled','A user cancelled booking #'.$id,null,$b['provider_id'],'booking');flash('success','Booking cancelled.');}redirect('bookings.php');}$st=$pdo->prepare('SELECT b.*,p.name provider_name,s.service_name FROM bookings b JOIN providers p ON p.id=b.provider_id JOIN services s ON s.id=b.service_id WHERE b.user_id=? ORDER BY b.booking_date DESC,b.booking_time DESC');$st->execute([$u['id']]);?><h2>My Bookings</h2><div class="service-card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Provider</th><th>Service</th><th>Date</th><th>Charge</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($st->fetchAll() as $b):?><tr><td>#<?=$b['id']?></td><td><?=e($b['provider_name'])?></td><td><?=e($b['service_name'])?></td><td><?=e($b['booking_date'])?> <?=e($b['booking_time'])?></td><td>PKR <?=number_format($b['charges'],2)?></td><td><?=badge($b['status'])?></td><td><?php if(in_array($b['status'],['Pending','Accepted','Confirmed'])):?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><input type="hidden" name="cancellation_reason" value="User requested cancellation"><button data-confirm="Cancel this booking?" class="btn btn-sm btn-outline-danger">Cancel</button></form><?php endif;if($b['status']==='Completed'):?><a class="btn btn-sm btn-outline-success" href="rating.php?booking=<?=$b['id']?>">Rate</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>